"use client";

import { useRef, useState } from "react";
import { Button } from "@/components/ui/Button";
import { SparkIcon } from "@/components/ui/icons";
import { PremiumAiPanel } from "@/components/ai/PremiumAiPanel";
import { AiGenerationState } from "@/components/ai/AiGenerationState";
import { AiDimensionList } from "@/components/ai/AiDimensionList";
import { AiSummary } from "@/components/ai/AiSummary";
import { useI18n } from "@/lib/i18n/context";
import { generateMatchBreakdownAction } from "@/app/(candidate)/external-jobs/actions";
import {
  aiRequestFor,
  canStartAiRequest,
  failedAiRequest,
  idleAiRequest,
  readyAiRequest,
  startedAiRequest,
  type AiRequestState,
} from "@/lib/ai/premium-request";
import { createLatestRequestGate, runLatest } from "@/lib/candidate/latest-request";
import { isEmptyMatchBreakdown } from "@/lib/api/external-jobs-adapters";
import type { ExternalMatchBreakdown as Breakdown } from "@/lib/types";

/**
 * The ranking, dimension by dimension.
 *
 * ## It decomposes an explanation, not a score
 *
 * The reader already has one number, from the deterministic ranker, and this
 * panel adds none. No dimension carries a rating, no total is assembled from
 * the statuses, and there is no bar or ring anywhere — a progress bar is a
 * percentage that happens to be drawn rather than written, and two numbers
 * about the same job leave a reader deciding which one is real.
 *
 * ## Four statuses, and the fourth is not a bad third
 *
 * STRONG, PARTIAL and GAP are claims about the fit. UNKNOWN is a claim about
 * the DATA: nobody stated this. An employer who published no salary has not
 * published a bad salary, and treating that silence as a shortfall would let
 * this product manufacture reasons a candidate falls short. It renders in a
 * neutral tone with a label that says so.
 *
 * ## Same lifecycle as the other three tools
 *
 * Idle until pressed, one request per press, superseded answers discarded.
 * Nothing is generated by opening the drawer or selecting this tab.
 */
export function ExternalMatchBreakdown({
  externalJobId,
}: {
  externalJobId: string;
}) {
  const { d } = useI18n();
  const [request, setRequest] = useState<AiRequestState<Breakdown>>(() =>
    idleAiRequest<Breakdown>(),
  );
  const gate = useRef(createLatestRequestGate());

  const current = aiRequestFor(request, externalJobId);

  function generate() {
    if (!canStartAiRequest(request, externalJobId)) return;

    setRequest(startedAiRequest<Breakdown>(externalJobId));

    void runLatest(gate.current, () => generateMatchBreakdownAction(externalJobId)).then(
      (outcome) => {
        if (outcome.stale) return;

        if (!outcome.ok) {
          setRequest(failedAiRequest<Breakdown>(externalJobId, "error"));
          return;
        }

        const result = outcome.value;
        if (!result.ok) {
          setRequest(
            failedAiRequest<Breakdown>(
              externalJobId,
              result.reason,
              result.requiredPlan ?? null,
            ),
          );
          return;
        }

        // A summary with no dimensions has broken nothing down. Reported as
        // unavailable — which offers a retry — rather than rendered as a
        // heading over an empty space where a table was promised.
        if (isEmptyMatchBreakdown(result.breakdown)) {
          setRequest(failedAiRequest<Breakdown>(externalJobId, "unavailable"));
          return;
        }

        setRequest(readyAiRequest(externalJobId, result.breakdown));
      },
    );
  }

  const breakdown = current.status === "ready" ? current.value : null;
  const showButton = current.status === "idle";

  return (
    <PremiumAiPanel
      title={d.externalJobs.matchBreakdownTitle}
      action={
        showButton ? (
          <Button variant="secondary" size="sm" onClick={generate}>
            <SparkIcon className="size-3.5" aria-hidden="true" />
            {d.externalJobs.matchBreakdownGenerate}
          </Button>
        ) : null
      }
    >
      {showButton ? (
        <p className="text-[12.5px] leading-relaxed text-ink-muted">
          {d.externalJobs.matchBreakdownInvite}
        </p>
      ) : null}

      <AiGenerationState
        status={current.status}
        capability="EXTERNAL_AI_SEARCH"
        requiredPlan={current.requiredPlan}
        onRetry={generate}
      />

      {breakdown ? (
        <div className="flex flex-col gap-3">
          {breakdown.summary ? <AiSummary text={breakdown.summary} /> : null}
          <AiDimensionList dimensions={breakdown.dimensions} />
        </div>
      ) : null}
    </PremiumAiPanel>
  );
}
